window.MediaLibrary={
images:[],videos:[],csrf:'',items:[],uploadLimit:0,
uploadLimitLabel(){return `${(this.uploadLimit/1024/1024).toFixed(0)} MB`},
async load(){const response=await fetch('/admin/api/media-list.php',{credentials:'same-origin'});if(!response.ok)throw new Error('Não foi possível carregar a biblioteca de mídia.');const data=await response.json();this.csrf=data.csrf;this.uploadLimit=Number(data.capabilities?.effective_upload_max_bytes)||0;this.items=data.items||[];this.images=this.items.filter(item=>item.kind==='image'&&item.processing_status==='ready').map(item=>({...item,versionId:item.active_version_id,src:item.derivatives?.filter(derivative=>derivative.format==='jpeg'||derivative.format==='png').at(-1)?.src||item.url,label:item.title,alt:item.default_alt||''}));this.videos=this.items.filter(item=>item.kind==='video').map(item=>({id:item.id,versionId:item.active_version_id,src:item.url,label:item.title,size:item.byte_size,status:item.processing_status,poster:item.poster?.src||'',posterId:item.poster?.id||null,posterTimestamp:item.poster?.timestamp??null,posters:item.posters||[]}));return this.items;},
async responseBody(response,fallback){const contentType=response.headers.get('content-type')||'';return contentType.includes('application/json')?response.json():fallback;},
async captureInitialPoster(file){const url=URL.createObjectURL(file),video=document.createElement('video');video.muted=true;video.playsInline=true;video.preload='auto';try{await new Promise((resolve,reject)=>{video.onloadedmetadata=()=>resolve();video.onerror=()=>reject(new Error('Não foi possível decodificar o vídeo enviado.'));video.src=url;video.load();});const duration=Number.isFinite(video.duration)?video.duration:0,target=duration>0?Math.min(.1,Math.max(0,duration-.001)):0;if(target>0){await new Promise((resolve,reject)=>{video.onseeked=resolve;video.onerror=()=>reject(new Error('Não foi possível posicionar o vídeo para criar o poster.'));video.currentTime=target;});}await new Promise((resolve,reject)=>{if(video.readyState>=2)return resolve();video.onloadeddata=resolve;video.onerror=()=>reject(new Error('O primeiro frame do vídeo não ficou disponível.'));});if(!video.videoWidth||!video.videoHeight)throw new Error('O primeiro frame do vídeo não possui dimensões válidas.');const canvas=document.createElement('canvas');canvas.width=video.videoWidth;canvas.height=video.videoHeight;canvas.getContext('2d').drawImage(video,0,0);const frame=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',.9));if(!frame)throw new Error('Não foi possível gerar o poster inicial.');return {frame,timestamp:target};}finally{video.removeAttribute('src');video.load();URL.revokeObjectURL(url);}},
async createPoster({mediaAssetId,mediaVersionId,timestamp,frame}){const data=new FormData();data.append('csrf',this.csrf);data.append('mediaAssetId',String(mediaAssetId));data.append('mediaVersionId',String(mediaVersionId));data.append('timestamp',String(timestamp));data.append('frame',frame,'poster.jpg');const response=await fetch('/admin/api/media-poster.php',{method:'POST',credentials:'same-origin',body:data});const body=await this.responseBody(response,null);if(!response.ok)throw new Error(body?.error||'O servidor não aceitou a criação do poster.');if(!body?.poster)throw new Error('O servidor retornou uma resposta inválida ao criar o poster.');await this.load();return body.poster;},
async upload(file,replaceAsset=''){if(this.uploadLimit&&file.size>this.uploadLimit)throw new Error(`O arquivo ultrapassa o limite permitido de ${this.uploadLimitLabel()}.`);const data=new FormData();data.append('csrf',this.csrf);data.append('file',file);if(replaceAsset)data.append('replace_asset',replaceAsset);const response=await fetch('/admin/api/media-upload.php',{method:'POST',credentials:'same-origin',body:data});const body=await this.responseBody(response,null);if(!response.ok){if(response.status===413||body?.error==='file_too_large')throw new Error(`O arquivo ultrapassa o limite permitido pelo servidor (${this.uploadLimitLabel()}).`);throw new Error(body?.error||'O servidor não aceitou o envio do arquivo.');}if(!body?.item)throw new Error('O servidor retornou uma resposta inválida ao enviar o arquivo.');if(body.item.kind==='video'&&!replaceAsset){try{const capture=await this.captureInitialPoster(file);body.item.poster=await this.createPoster({mediaAssetId:body.item.id,mediaVersionId:body.item.active_version_id,timestamp:capture.timestamp,frame:capture.frame});body.item.posterId=body.item.poster.id;body.item.posterTimestamp=body.item.poster.timestamp;}catch(error){body.item.poster=null;body.item.posterError=error.message;}}await this.load();return body.item;},
async uses(assetId){const response=await fetch('/admin/api/media-usage.php?asset='+encodeURIComponent(assetId),{credentials:'same-origin'});const body=await response.json();if(!response.ok)throw new Error(body.error||'usage_failed');return body.uses||[];}
};
const loadMediaLibrary=window.MediaLibrary.load.bind(window.MediaLibrary);window.MediaLibrary.load=async function(){const items=await loadMediaLibrary();this.videos=this.videos.map(video=>{const asset=this.items.find(item=>Number(item.id)===Number(video.id))||{};return {...video,duration:Number.isFinite(Number(asset.duration))&&Number(asset.duration)>0?Number(asset.duration):null,createdAt:asset.created_at||'',created_at:asset.created_at||''};});return items;};
